------------------
---- MONITORS ----
------------------

-- See https://wiki.hypr.land/Configuring/Basics/Monitors/
hl.monitor({
    output   = "HDMI-A-1",
    mode     = "1920x1080@60",
    position = "0x0",
    scale    = "auto",
})

hl.monitor({
    output   = "DP-3",
    mode     = "2560x1440@165",
    position = "1920x-270",
    scale    = "auto",
})

-- Assign workspaces to monitors gapsin = gap between apps, gapsout gap to the border of screen

hl.workspace_rule({
    workspace = 1,
    monitor = "DP-3",
    decorate = true,
})

hl.workspace_rule({
    workspace = 2,
    monitor = "DP-3",
    decorate = true,
})

hl.workspace_rule({
    workspace = 3,
    monitor = "DP-3",
    decorate = true,
})

hl.workspace_rule({
    workspace = 4,
    monitor = "DP-3",
    decorate = true,
})

hl.workspace_rule({
    workspace = 5,
    monitor = "DP-3",
    decorate = true,
})

hl.workspace_rule({
    workspace = 6,
    monitor = "DP-3",
    decorate = true,
})

hl.workspace_rule({
    workspace = 7,
    monitor = "DP-3",
    decorate = true,
})

hl.workspace_rule({
    workspace = 8,
    monitor = "HDMI-A-1",
    decorate = true,
})

hl.workspace_rule({
    workspace = 9,
    monitor = "HDMI-A-1",
    decorate = true,
})

hl.workspace_rule({
    workspace = 10,
    monitor = "HDMI-A-1",
    decorate = true,
})

