-- Autostart
hl.on("hyprland.start", function()
    hl.exec_cmd("hyprpaper")
    hl.exec_cmd("hyprctl setcursor Sweet-cursors 24")
    hl.exec_cmd("waybar")
    hl.exec_cmd("[workspace 10 silent] discord")
    hl.exec_cmd("mako")
    hl.exec_cmd("/usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1")
    hl.exec_cmd("/usr/bin/numlockx")
    hl.exec_cmd("sh -c \"sleep 2 && echo 245000000 > /sys/class/drm/card1/device/hwmon/hwmon*/power1_cap\"")
    hl.exec_cmd("sh -c \"echo performance > /sys/devices/system/cpu/cpu*/cpufreq/scaling_governor\"")
end)
